sys_script_include.script:
var IncidenteLogisticoUtils = Class.create();
IncidenteLogisticoUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    verificarDuplicidade: function() {
        var rotaId = this.getParameter('sysparm_rota');

        if (!rotaId) {
            return 'false';
        }

        var grIncidente = new GlideRecord('x_2066889_centra_0_incidente_logistico');

        // Usando o Column Name exato que apareceu na tua imagem
        grIncidente.addQuery('rota', rotaId);
        grIncidente.query();

        if (grIncidente.hasNext()) {
            return 'true'; 
        } else {
            return 'false'; 
        }
    },

    type: 'IncidenteLogisticoUtils'
});
